def _write_part(out, v, depth):
    _closed_enum(PartKind, v.kind)
    out += b"{"
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "kind")
    out += b": "
    _esc(out, v.kind)
    if v.text:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "text")
        out += b": "
        _esc(out, v.text)
    if v.digest:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "digest")
        out += b": "
        _esc(out, v.digest)
    if v.media_type:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "media_type")
        out += b": "
        _esc(out, v.media_type)
    if v.call_id:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "call_id")
        out += b": "
        _esc(out, v.call_id)
    if v.name:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "name")
        out += b": "
        _esc(out, v.name)
    if v.arguments:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "arguments")
        out += b": "
        _esc(out, v.arguments)
    out += b"\n"
    _pad(out, depth)
    out += b"}"


