def _write_options(out, v, depth):
    out += b"{"
    first = True
    if v.max_output != 0:
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "max_output")
        out += b": "
        _num(out, v.max_output)
    if v.temperature is not None:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "temperature")
        out += b": "
        _write_temperature(out, v.temperature, depth + 1)
    if v.stop:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "stop")
        out += b": "
        _strs(out, v.stop, depth + 1)
    if v.json_schema:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "json_schema")
        out += b": "
        _esc(out, v.json_schema)
    if not first:
        out += b"\n"
        _pad(out, depth)
    out += b"}"


