        _args.operation = operation
        _args.cursor = cursor
        _args.max_deltas = max_deltas
        _args.max_bytes = max_bytes
        _args.wait_ms = wait_ms
        _arguments = _service_encode(_write_oa_chat_observe_arguments, _args, 1)
        _service_decode(_read_oa_chat_observe_arguments, _arguments, 1)
        _request = _service_request("abstraction.inference/chat@1", "Observe", _arguments)
        _payload = _service_response(self._transport.exchange_frame(_request), "abstraction.inference/chat@1", "Observe")
        _result = _service_decode(_read_oa_chat_observe_result, _payload, 1)
