class Operator:
    """Administer the runtime's inference hosts, the gateway window and its local
    keys, and read the inference audit. Each call is a rights decision for the
    bound operator subject; same-account identity alone grants nothing. A
    decision point that cannot answer reads unavailable."""

    def hosts(self) -> HostList:
        """Read the configured hosts, their router state and each hosted
        credential's spend today, from the registry's declarations of role host.
        Gated by abstraction.inference/host.manage on resource account."""
        raise NotImplementedError

    def add_host(self, expected_revision: str, host: HostEntry) -> HostChange:
        """Conditionally add one host, kept as a registry declaration of role host.
        Gated by host.manage. For the bound operator program and the runtime's
        other operator programs it also writes the permit rule
        abstraction.inference/complete on host:<name>, and for a hosted host
        with a credential it writes the runtime's own permit rule
        abstraction.credentials/apply on credential:<name>, which the router's
        listing reads need. Existing rules are left as they are."""
        raise NotImplementedError

    def remove_host(self, expected_revision: str, name: str) -> HostChange:
        """Conditionally remove one host; operations already admitted run to their
        end. Gated by host.manage. A host the installation or a product declared
        is disabled by name instead of removed. Rules are left as they are."""
        raise NotImplementedError

    def keys(self) -> KeyList:
        """Read the local keys of the receiving account. Gated by
        abstraction.inference/key.issue on resource account."""
        raise NotImplementedError

    def issue_key(self, program: str, credential: str) -> KeyIssued:
        """Mint a local key for program, an absolute executable path, and hold it
        in the platform store. credential, when not empty, names the hosted
        credential the window's requests for that program may spend under. Gated
        by key.issue. The key grants nothing: the window still binds the peer,
        requires that program, and decides abstraction.inference/complete and
        credentials apply for it."""
        raise NotImplementedError

    def revoke_key(self, program: str) -> KeyRevoked:
        """Destroy the active local key of program. Gated by key.issue."""
        raise NotImplementedError

    def audit(self, cursor: int, max_entries: int) -> AuditPage:
        """Read retained inference decisions from both routes. Gated by
        abstraction.inference/audit.read on resource account. cursor 0 starts at
        the oldest retained entry; max_entries is 1..256."""
        raise NotImplementedError

    def requests(self, cursor: int, max_entries: int) -> RequestPage:
        """Read retained inference requests from both routes with recorded
        selection and placement. Uses the Audit journal, cursor and retention.
        Gated by abstraction.inference/audit.read on resource account. cursor 0
        starts at the oldest retained entry; max_entries is 1..256."""
        raise NotImplementedError

    def gateway(self) -> GatewayState:
        """Read the gateway window setting and whether the window listens now.
        Gated by abstraction.inference/host.manage on resource account."""
        raise NotImplementedError

    def set_gateway(self, expected_revision: str, open: bool, address: str) -> GatewayChange:
        """Conditionally write the gateway window setting to the runtime state and
        apply it to the running runtime: open listens on address, and closed
        stops the listener and every window connection. address is
        127.0.0.1:<port>; empty keeps the recorded address when opening, and
        127.0.0.1:8793 when none is recorded. The setting survives a restart.
        Gated by host.manage."""
        raise NotImplementedError

    def program_budgets(self, credential: str) -> ProgramBudgetPage:
        """Read one credential's durable per-program budgets and observed usage in
        the existing ceiling owner. Gated by abstraction.inference/host.manage
        on resource account for the native bound operator."""
        raise NotImplementedError

    def set_program_budget(self, request: ProgramBudgetChange) -> ProgramBudgetResult:
        """Conditionally set one receiving-account native program's budget for
        credential in the existing ceiling state. Absent budget removes its
        configured limit while retaining usage; a present all-zero budget
        records explicit No limit. Gated by host.manage. The native presenter
        supplies the question's bound program; this operation grants no
        credential use or inference authority."""
        raise NotImplementedError


